pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount, bytes calldata data) public {
        amount = bound(amount, 1, 100 ether);
        vm.deal(address(c), 2 * amount);

        Reverter reverter = new Reverter();

        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        uint256 depositsBefore = c.depositsCount();

        vm.prank(owner);
        bool ok;
        try c.sendMoney(address(reverter), amount, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("Reverter always fails");
    }
}
